import csv
import re

_EXPECTED_WIDTH = 9
_HEADER_NAMES = {
    "date",
    "time",
    "qty",
    "quantity",
    "productid",
    "price",
    "producttype",
    "productdescription",
    "url",
    "comments",
    "comment",
}


def _normalize_header_value(value):
    return re.sub(r"[^a-z0-9]+", "", value.strip().lower())


def _manual_csv_parse(text):
    records = []
    row = []
    field = []
    in_quotes = False
    i = 0
    length = len(text)

    while i < length:
        char = text[i]

        if in_quotes:
            if char == '"':
                if i + 1 < length and text[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                field.append(char)
            i += 1
            continue

        if char == '"' and not field:
            in_quotes = True
        elif char == ",":
            row.append("".join(field))
            field = []
        elif char == "\r" or char == "\n":
            row.append("".join(field))
            field = []
            records.append(row)
            row = []
            if char == "\r" and i + 1 < length and text[i + 1] == "\n":
                i += 1
        else:
            field.append(char)
        i += 1

    if field or row or (length > 0 and text[-1] == ","):
        row.append("".join(field))
        records.append(row)

    return records


def _read_records(raw_csv):
    try:
        csv.field_size_limit(100000000)
    except (OverflowError, csv.Error):
        pass

    try:
        return list(csv.reader(
            raw_csv.splitlines(keepends=True),
            delimiter=",",
            quotechar='"',
            doublequote=True,
            strict=False,
        ))
    except csv.Error:
        return _manual_csv_parse(raw_csv)


def _is_blank_row(row):
    return not row or all(value == "" for value in row)


def _header_score(row):
    normalized = [_normalize_header_value(value) for value in row]
    return sum(1 for value in normalized if value in _HEADER_NAMES)


def _find_header_index(records):
    best_index = None
    best_score = -1

    for index, row in enumerate(records):
        if _is_blank_row(row):
            continue
        score = _header_score(row)
        width_bonus = 2 if len(row) == _EXPECTED_WIDTH else 0
        total = score + width_bonus
        if score >= 4 and total > best_score:
            best_index = index
            best_score = total
            if score >= 8 and len(row) == _EXPECTED_WIDTH:
                break

    if best_index is not None:
        return best_index

    for index, row in enumerate(records):
        if not _is_blank_row(row) and len(row) == _EXPECTED_WIDTH:
            return index

    for index, row in enumerate(records):
        if not _is_blank_row(row):
            return index

    return None


def _looks_like_url(value):
    return re.match(r"^\s*(?:https?|ftp)://", value, re.IGNORECASE) is not None


def _normalize_width(row, width, url_index):
    values = list(row)

    if len(values) == width:
        return values

    if url_index is not None:
        actual_url_index = None
        for index, value in enumerate(values):
            if _looks_like_url(value):
                actual_url_index = index
                break

        if actual_url_index is not None:
            before = values[:actual_url_index]
            url_value = values[actual_url_index]
            after = values[actual_url_index + 1:]

            if len(before) > url_index:
                merge_index = max(0, url_index - 1)
                before = (
                    before[:merge_index]
                    + [",".join(before[merge_index:])]
                )
            elif len(before) < url_index:
                before.extend([""] * (url_index - len(before)))

            result = before[:url_index] + [url_value]
            remaining_width = width - len(result)

            if remaining_width > 0:
                if len(after) <= remaining_width:
                    result.extend(after)
                    result.extend([""] * (remaining_width - len(after)))
                else:
                    result.extend(after[:remaining_width - 1])
                    result.append(",".join(after[remaining_width - 1:]))

            return result[:width]

    if len(values) < width:
        return values + [""] * (width - len(values))

    if width <= 1:
        return [",".join(values)]

    return values[:width - 1] + [",".join(values[width - 1:])]


def parse_csv(raw_csv: str):
    records = _read_records(raw_csv)
    header_index = _find_header_index(records)

    if header_index is None:
        return {"columns": [], "rows": []}

    raw_header = list(records[header_index])
    if raw_header:
        raw_header[0] = raw_header[0].lstrip("\ufeff")

    if len(raw_header) < _EXPECTED_WIDTH:
        columns = raw_header + [""] * (_EXPECTED_WIDTH - len(raw_header))
    elif len(raw_header) > _EXPECTED_WIDTH:
        columns = raw_header[:_EXPECTED_WIDTH - 1] + [
            ",".join(raw_header[_EXPECTED_WIDTH - 1:])
        ]
    else:
        columns = raw_header

    header_signature = tuple(_normalize_header_value(value) for value in columns)
    url_index = None
    for index, value in enumerate(header_signature):
        if value == "url":
            url_index = index
            break

    rows = []
    for raw_row in records[header_index + 1:]:
        if _is_blank_row(raw_row):
            continue

        candidate = list(raw_row)
        if candidate:
            candidate[0] = candidate[0].lstrip("\ufeff")

        if len(candidate) == len(columns):
            signature = tuple(
                _normalize_header_value(value) for value in candidate
            )
            if signature == header_signature:
                continue

        rows.append(_normalize_width(candidate, len(columns), url_index))

    return {"columns": columns, "rows": rows}
